    "explanation": "In a monarchical system, the ultimate authority or sovereignty is traditionally vested in the royal family—specifically, the monarch. Although modern constitutional monarchies often have democratic elements, the traditional principle of monarchy holds that the crown is the source of sovereign power, rather than the people, a legislature, or the military."
