    "id": "government-1788725001454-211-1465",
    "questionText": "The Igbo political system was based on (JAMB 2015)",
    "options": [
      "Age Grades",
      "Umunna",
      "Family ties",
      "Umuada"
    ],
    "correctAnswer": "B",
    "explanation": "The Igbo pre-colonial political system was fundamentally decentralized and based on kinship structures, with the Umunna serving as the primary unit of political organization. The Umunna refers to a patrilineal kinship group or extended family unit, consisting of individuals who share a common male ancestor. Each Umunna was led by the eldest male, known as the Diokpala, who, along with other elders, played a significant role in decision-making and governance within the community. This structure ensured that authority was distributed among various family heads, fostering a republican and egalitarian society"
